module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [3:0];
reg [2:0] SP;

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 4;
        for (integer i = 0; i < 4; i = i + 1) begin
            stack_mem[i] <= 0;
        end
        EMPTY <= 1;
        FULL <= 0;
    end else if (EN) begin
        if (!RW && !FULL) begin
            stack_mem[SP - 1] <= dataIn;
            SP <= SP - 1;
            FULL <= SP == 0 ? 1 : 0;
            EMPTY <= SP == 4 ? 1 : 0;
        end else if (RW && !EMPTY) begin
            dataOut <= stack_mem[SP];
            stack_mem[SP] <= 0;
            SP <= SP + 1;
            FULL <= SP == 0 ? 1 : 0;
            EMPTY <= SP == 4 ? 1 : 0;
        end
    end
end

endmodule
